<?php
$patientReviewFile = PROJECT_ROOT . '/content/patient-reviews.json';
$patientReviewData = is_file($patientReviewFile)
    ? json_decode(file_get_contents($patientReviewFile), true, 512, JSON_THROW_ON_ERROR)
    : ['heading' => 'Отзывы о враче', 'lead' => 'Пациенты о лечении у Магомеда Раджабовича Расулова', 'reviews' => []];
$patientReviews = $patientReviewData['reviews'] ?? [];
?>
<section class="dz-source-reviews dz-light" data-review-carousel data-review-page-size="4"><div class="max-w-[1440px] mx-auto px-[22px] md:px-[80px] py-[50px] md:py-[100px]"><<?= $route === 'reviews' ? 'h1' : 'h2' ?> class="md:text-p36 text-p24 text-darkText mb-[20px]"><?= e($patientReviewData['heading']) ?></<?= $route === 'reviews' ? 'h1' : 'h2' ?>><p class="md:text-p22 text-p16 text-darkText mb-[30px]"><?= e($patientReviewData['lead']) ?></p><div class="dz-source-review-grid"><?php foreach ($patientReviews as $i => $review): ?><article data-review-card class="dz-source-review-card" <?= $i > 3 ? 'hidden' : '' ?>><p class="dz-source-review-text"><?= nl2br(e($review['text']), false) ?></p><button type="button" data-read-review aria-haspopup="dialog" aria-controls="patient-review-detail">Читать далее</button><div class="dz-source-review-details"><div><span>Специалист</span><p><?= e($review['doctor']) ?></p></div><div><span>Оценка</span><p><?= e(number_format((float) $review['rating'], 1, ',', '')) ?> из 5</p></div></div><p class="dz-source-review-author"><?= e($review['patient']) ?><small><?= e($review['publishedAt']) ?></small></p></article><?php endforeach; ?></div><div class="dz-source-review-nav"><span data-review-status></span><button class="dz-icon-btn" type="button" data-review-prev aria-label="Предыдущие отзывы"><?= icon('chevron', 'dz-prev') ?></button><button class="dz-icon-btn" type="button" data-review-next aria-label="Следующие отзывы"><?= icon('chevron', 'dz-next') ?></button></div><div class="dz-source-review-actions"><?php if($route!=='reviews'): ?><a class="dz-btn" href="/reviews">СМОТРЕТЬ ВСЕ ОТЗЫВЫ</a><?php endif; ?><a class="dz-btn dz-review-secondary" href="mailto:<?= COMPANY_EMAIL ?>?subject=<?= rawurlencode('Отзыв о Доме Зубов') ?>">ОСТАВИТЬ ОТЗЫВ</a></div></div></section>
